  FT["PH-H4429"] = {"id":"PH-H4429","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5632_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of Napayong Island, Located in Taal Lake, Province of Batangas, to Laurel Island","orig":"An Act Changing the Name of Napayong Island, Located in Taal Lake, Province of Batangas, to Laurel Island"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5632","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5632_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4429-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Napayong Island, located in Taal Lake, Province of Batangas, is hereby changed to Laurel Island."}},{"id":"PH-H4429-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4430"] = {"id":"PH-H4430","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5633_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of Kamuning Road, Kamuning District, Quezon City, to Benedicto Padilla Avenue in Honor of the Late Congressman Benedicto Padilla","orig":"An Act Changing the Name of Kamuning Road, Kamuning District, Quezon City, to Benedicto Padilla Avenue in Honor of the Late Congressman Benedicto Padilla"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5633","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5633_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4430-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Hereafter, Kamuning Road in Kamuning District, Quezon City, shall be known as Benedicto Padilla Avenue in honor of the late Congressman Benedicto Pa­dilla of the First District of the Province of Rizal."}},{"id":"PH-H4430-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4431"] = {"id":"PH-H4431","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5634_1969.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Numancia市","en":"An Act Establishing a Breeding Station in the Municipality of Numancia, Province of Surigao Del Norte","orig":"An Act Establishing a Breeding Station in the Municipality of Numancia, Province of Surigao Del Norte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5634","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5634_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4431-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established a breeding station in the Municipality of Numancia, Province of Surigao del Norte, under the supervision of the Director of the Bureau of Animal Industry."}},{"id":"PH-H4431-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Director of the Bureau of Animal Industry shall appoint such personnel as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H4431-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated, for the fiscal year nineteen hundred and seventy. Thereafter, such sums as may be needed to carry out its maintenance and operation shall be included in the annual General Appropriations Act."}},{"id":"PH-H4431-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4432"] = {"id":"PH-H4432","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5635_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Increasing the Bed Qapac1ty of Batac General Hospital in the Municipality of Batac, Province of 1locos Norte, and Appropriating Funds Therefor","orig":"An Act Increasing the Bed Qapac1ty of Batac General Hospital in the Municipality of Batac, Province of 1locos Norte, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 5635","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5635_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4432-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Batac General Hospital in the Municipality of Batac, Province of Ilocos Norte, is hereby increased from twenty-five to fifty beds."}},{"id":"PH-H4432-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Such sums as may be needed for the operation of the additional facilities shall be included in the annual General Appropriations Act."}},{"id":"PH-H4432-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4433"] = {"id":"PH-H4433","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5636_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for the Establishment of a Community Hospital in the Municipality of Albor, Province of Surigao Del Norte, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of a Community Hospital in the Municipality of Albor, Province of Surigao Del Norte, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 5636","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5636_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4433-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Medical Services, a community hospital in the Municipality of Albor, Province of Surigao del Norte, to be known as the Albor Community Hospital."}},{"id":"PH-H4433-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of three hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred sixty-nine including the construction of the hospital building thereof. Thereafter, such sum as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H4433-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
