  FT["PH-H4437"] = {"id":"PH-H4437","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5640_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Dapa市","en":"An Act Establishing a Marine Fisheries Demonstration Station and Nursery At Any Suitable Place in the Municipality of Dapa, Siargao Island, Province of Surigao Del Norte, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing a Marine Fisheries Demonstration Station and Nursery At Any Suitable Place in the Municipality of Dapa, Siargao Island, Province of Surigao Del Norte, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 5640","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5640_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4437-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established and maintained under the supervision of the Commissioner of Fisheries, a marine fisheries demonstration station and nursery in any suitable coastal barrio in the Municipality of Dapa, Siargao Island, Province of Surigao del Norte, to be known as the Siargao Fisheries Demonstration Station and Nursery."}},{"id":"PH-H4437-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, to carry into effect the purposes of this Act during the fiscal year nineteen hundred sixty-nine. Thereafter, the necessary amount for the operation and maintenance of said station shall be included in the annual General Appropriations Act."}},{"id":"PH-H4437-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4438"] = {"id":"PH-H4438","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5641_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Municipality of Sapao, Province of Surigao Del Norte, to Sta. Monica","orig":"An Act Changing the Name of the Municipality of Sapao, Province of Surigao Del Norte, to Sta. Monica"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5641","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5641_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4438-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Municipality of Sapao, Province of Surigao del Norte, is hereby changed to Sta. Monica."}},{"id":"PH-H4438-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4439"] = {"id":"PH-H4439","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5642_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating the Municipality Narra, Province of Palawan","orig":"An Act Creating the Municipality Narra, Province of Palawan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5642","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5642_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4439-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrios of Malatgao, Tinagong-dagat, Taritien, Antipoloan, Teresa, Panacan, Narra, Caguisan, Batang-batang, Bato-bato, Barirao, Malinao, Sandoval, Dumagueiia, El Vita, Calategas, Arumayuan, Tacras, Borirao and that part of Barrio Abo-abo now belonging to the Municipality of Aborlan, Province of Palawan, are separated from said municipality and constituted into a distinct and independent municipality, to be known as the Municipality of Narra. The seat of the new municipality shall be in the present site of Barrio Narra."}},{"id":"PH-H4439-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Mayor of the Municipality of Aborlan elected in the elections of November 15, 1967, shall be the mayor of the said Municipality of Narra. The vice-mayor of Aborlan elected in the last elections shall be the mayor of Aborlan. The councilor who obtained the highest number of votes in the last elections shall be the vice-mayor of Narra and the one who obtained the second highest shall be the vice-mayor of Aborlan. The appointment of councilors to fill the vacant positions in both municipalities shall be made in accordance with the provisions of Republic Act Numbered Five thousand one hundred eighty-five."}},{"id":"PH-H4439-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4440"] = {"id":"PH-H4440","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5643_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating the Municipality of Tubajon in the Province of Surigao Del Norte","orig":"An Act Creating the Municipality of Tubajon in the Province of Surigao Del Norte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5643","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5643_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4440-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following territory is separated from the Municipality of Loreto, Province of Surigao del Norte, and constituted into a distinct and independent municipality, to be known as the Municipality of Tubajon, same province.\n\"The territory starting from the Northwestern coastal shore at Loreto, at Lisub Cove, as point \"A\" following a straight line, Southwest toward Pili (Caracan) Hill at Barrio Mabini as Point \"B\"; then from Point \"B\" at Pili Hill following a straight line to Payao Point at Malinao Inlet as Point \"C\"; then Payao Point following the coast line Southward to Balwarto Point; then to Awing Point, the Municipal Boundary of the Municipality of Loreto, mother municipality of Tubaion, and the Municipality of Albor; then from Awing Point following the coast line Northward to Lisub Cove Point \"A\" point of the beginning. Said territory comprises the Barrios of San Vicente, Santa Cruz, Roxas. Mabini, Malinao, Navarro, and Imelda.\"\nThe seat of government of the new Municipality of Tubajon shall be in the present site of Barrios San Vicente and Santa Cruz."}},{"id":"PH-H4440-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first mayor, vice-mayor, and councilors of the new municipality shall be elected in the next general elections for local officials."}},{"id":"PH-H4440-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4441"] = {"id":"PH-H4441","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5644_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Municipality of Faire in the Province of Cagayan to Santo Niño","orig":"An Act Changing the Name of the Municipality of Faire in the Province of Cagayan to Santo Niño"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5644","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5644_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4441-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Municipality of Faire, in the Province of Cagayan is hereby changed to Santo Niño."}},{"id":"PH-H4441-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4442"] = {"id":"PH-H4442","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5645_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating the Municipality of Alamada in the Province of Cotabato","orig":"An Act Creating the Municipality of Alamada in the Province of Cotabato"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5645","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5645_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4442-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrios of Kifeakubong, Pacao, Polayagan, Camansi, Mapurok, Macabasa, Pigcawaran, Kangayan, Dado, Guiling, Bao, Malitubog, and Paruayan in the Municipality of Libungan, and the sitios of Marakabak, Pidatan, Dimampao, and Kurope in the Municipality of Carmen, all in the Province of Cotabato, are separated from said municipalities and constituted into a distinct and independent municipality, to be known as the Municipality of Alamada. The seat of government of the new municipality shall be in the present site of the barrio of Kitakubong, same province.\nThe Municipality of Alamada shall be bounded as follows:\n\"The point of origin should be the common western corner monument of Lot No. 161 and Lot No. 159, Pls-357, along the Libungan-Edcor Road; thence due East until it reaches the left bank of Malitubog River; thence northerly, northeasterly and northwesterly following Malitubog River upstream until it reaches or intersects the Cotabato-Lanao del Sur boundary line; thence westerly, northwesterly and southwesterly following the Cotabato Lanao del Sur boundary until it reaches the common boundary corner of the mother Municipality of Libungan and the Municipality of Buldon, which is at the tip or peak of the Latukan Volcano; thence southwesterly and southeasterly following the boundary line of the mother Municipality of Libungan until it reaches the common corner monument of the three municipalities namely: Buldon, Pigcawayan, and the mother Municipality of Libungan prolonging the same until it reaches a point 15 kilometers South; thence due East across the Akir-Akir Mountain until it reaches the point of origin.\""}},{"id":"PH-H4442-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first mayor, vice-mayor, and councilors of the new municipality shall be elected in a special elections to coincide with the presidential elections in November of nineteen hundred and sixty-nine."}},{"id":"PH-H4442-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4443"] = {"id":"PH-H4443","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5646_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Municipality of San Pedro in the Province of Oriental Mindoro","orig":"An Act Changing the Name of the Municipality of San Pedro in the Province of Oriental Mindoro"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5646","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5646_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4443-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Municipality of San Pedro in the Province of Oriental Mindoro is hereby changed to Bulalakao."}},{"id":"PH-H4443-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4444"] = {"id":"PH-H4444","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5647_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Municipality of Nuling in the Province of Cotabato, to Sultan Kudarat","orig":"An Act Changing the Name of the Municipality of Nuling in the Province of Cotabato, to Sultan Kudarat"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5647","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5647_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4444-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Municipality of Nuling in the Province of Cotabato is hereby changed to Sultan Kudarat."}},{"id":"PH-H4444-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4445"] = {"id":"PH-H4445","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5648_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for the Establishment of a National Shrine in the Municipality Op Batac, Province of Ilocos Norte, to Be Known as Ricarte Shrine","orig":"An Act Providing for the Establishment of a National Shrine in the Municipality Op Batac, Province of Ilocos Norte, to Be Known as Ricarte Shrine"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5648","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5648_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4445-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is established in the Municipality of Batae, Province of Ilocos Norte, a national shrine to be known as Ricarte Shrine, which shall comprise the land and the house built thereon where the late General Artemio Ricarte was born, as well as lands adjacent thereto not to exceed two thousand square meters whose acquisition by negotiation or expropriation is hereby authorized."}},{"id":"PH-H4445-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"There shall be constructed on any vacant place in the land, birthplace of the late General Artemio Ricarte, a house wherein shall be preserved the relics in the General's life."}},{"id":"PH-H4445-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4446"] = {"id":"PH-H4446","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5649_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for the Establishment of a National Shrine in the Municipality of Batac, Province of Ilocos Norte, to Be Known as Aglipay Shrine","orig":"An Act Providing for the Establishment of a National Shrine in the Municipality of Batac, Province of Ilocos Norte, to Be Known as Aglipay Shrine"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5649","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5649_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4446-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is established in the Municipality of Batac, Province of Ilocos Norte, a national shrine to be known as Aglipay Shrine, which shall comprise the land and the house built thereon where the late Bishop Gregorio Aglipay was born, as well as lands adjacent thereto not to exceed two thousand square meters whose acquisition by negotiation or expropriation is hereby authorized."}},{"id":"PH-H4446-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"There shall be constructed, on any vacant place in the land where the late Bishop Gregorio Aglipay was born, a house wherein shall be preserved the relics in the Bishop's life."}},{"id":"PH-H4446-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4447"] = {"id":"PH-H4447","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5650_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Province of Western Samar to Samar","orig":"An Act Changing the Name of the Province of Western Samar to Samar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5650","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5650_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4447-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Province of Western Samar is hereby changed to Samar."}},{"id":"PH-H4447-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4448"] = {"id":"PH-H4448","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5651_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating the Provinces of Northern Samar, Eastern Samar, and Western Samar.","orig":"An Act Amending Republic Act Numbered Forty-Two Hundred and Twenty-One, Entitled \"An Act Creating the Provinces of Northern Samar, Eastern Samar, and Western Samar.\""},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5651","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5651_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4448-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Republic Act Numbered Forty-two hundred and twenty-one is hereby amended by inserting between Section nine and Section ten thereof, a new section which shall read as follows:\n\"Section 9-A. Officers and employees, whether occupying positions in the classified or unclassified service in the Province of Samar who are separated from the service due to its division into three provinces and who are re-appointed after the division of said province takes effect shall be deemed to have rendered continuous service and shall retain the status of their previous and/or later appointments, whichever is more advantageous to the said officers and employees.\""}},{"id":"PH-H4448-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4449"] = {"id":"PH-H4449","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5652_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for the Establishment of a Post Office in the Municipality of San Isidro, Province of Surigao Del Norte, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of a Post Office in the Municipality of San Isidro, Province of Surigao Del Norte, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5652","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5652_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4449-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established a post office with one postmaster and one letter carrier in the Municipality of San Isidro, Province of Surigao del Norte."}},{"id":"PH-H4449-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, to carry out the purposes of this Act. Thereafter, such sum as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H4449-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4450"] = {"id":"PH-H4450","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5653_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Guiuan市","en":"An Act Creating a Branch Office of the Register of Deeds in the Province of Samar, With Permanent Station At the Municipality of Guiuan, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Creating a Branch Office of the Register of Deeds in the Province of Samar, With Permanent Station At the Municipality of Guiuan, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5653","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5653_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 3 条，缺 2）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4450-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby created a branch office of the Register of Deeds in the Province of Samar, with permanent station at the Municipality of Guiuan, which shall be under the immediate control and supervision of a deputy register of deeds to be appointed by the Secretary of Justice. The said deputy register of deeds shall be considered as Class III under WAPCO classification and shall receive compensation within the range now provided by laws and regulations. He shall be assisted by such additional personnel, likewise appointed by the Secretary of Justice, as may be necessary to carry out the duties appurtenant to the said branch office.\nSection 2 The sum of fifty thousand pesos, or so much thereof as may be necessary, is hereby authorized to be appropriated, out .of any funds in the National Treasury not otherwise appropriated, to carry out the purposes of this Act. Thereafter, the sums necessary for the same purpose shall be included in the annual General Appro­priations Act."}},{"id":"PH-H4450-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4451"] = {"id":"PH-H4451","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5654_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating Additional Positions of Assistant Provincial Fiscal in the Province of Cebu, Amending for This Purpose Section Sixteen Hundred Seventy-Four of the Revised Administrative Code, as Amended","orig":"An Act Creating Additional Positions of Assistant Provincial Fiscal in the Province of Cebu, Amending for This Purpose Section Sixteen Hundred Seventy-Four of the Revised Administrative Code, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 5654","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5654_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4451-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The provision of Section sixteen hundred 1 seventy-four of the Revised Administrative Code as amended, relative to the number of assistant provincial fiscals in the Province of Cebu, is further amended to read as follows:\n\"Cebu, twenty-four assistant provincial fiscals;\""}},{"id":"PH-H4451-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4452"] = {"id":"PH-H4452","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5655_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for the Establishment of An Emergency Hospital in the Municipality of Lupon, Province of Davaq Oriental, to Be Known as Lupon Emergency Hospital, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of An Emergency Hospital in the Municipality of Lupon, Province of Davaq Oriental, to Be Known as Lupon Emergency Hospital, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 5655","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5655_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4452-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be 'established, under the direct supervision of the Director of Medical Services, an emergency hospital in the Municipality of Lupon, Province of Davao Oriental, to be known as Lupon Emergency Hospital."}},{"id":"PH-H4452-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred seventy. Thereafter, such sums as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H4452-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4453"] = {"id":"PH-H4453","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5656_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Cauayan市","en":"An Act Establishing a Tuberculosis Pavilion in the Municipality of Cauayan, Province of Isabela, and Authorizing the Appropriation of Funds Therefore","orig":"An Act Establishing a Tuberculosis Pavilion in the Municipality of Cauayan, Province of Isabela, and Authorizing the Appropriation of Funds Therefore"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5656","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5656_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4453-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established under the supervision of the Director of Medical Services, a tuberculosis pavilion which shall be a part or extension of the Cauayan Emergency Hospital."}},{"id":"PH-H4453-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred seventy. Thereafter, such sum as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H4453-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4454"] = {"id":"PH-H4454","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5657_1969.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Koronadal市","en":"An Act Converting the Rural Health Center in the Municipality of Koronadal, Province of South Cotabato, Into a General Hospital, to Be Known as Koronadal General Hospital and Authorizing the Appropriation of Funds Therefor","orig":"An Act Converting the Rural Health Center in the Municipality of Koronadal, Province of South Cotabato, Into a General Hospital, to Be Known as Koronadal General Hospital and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 5657","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5657_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4454-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The rural health center in the Municipality of Koronadal, Province of South Cotabato, is hereby converted into the Koronadal General Hospital with fifty hospital beds."}},{"id":"PH-H4454-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Health shall issue the rules and regulations for the implementation of this Act."}},{"id":"PH-H4454-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during fiscal year nineteen hundred seventy. Thereafter, such sums as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H4454-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4455"] = {"id":"PH-H4455","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5658_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Mauban市","en":"An Act Declaring the Municipality of Mauban, Province of Quezon, a Permanent Subport","orig":"An Act Declaring the Municipality of Mauban, Province of Quezon, a Permanent Subport"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5658","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5658_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4455-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Municipality of Mauban, Province of Quezon, is hereby declared a permanent subport."}},{"id":"PH-H4455-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4456"] = {"id":"PH-H4456","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5659_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating the Municipality of Balete in the Province of Batangas","orig":"An Act Creating the Municipality of Balete in the Province of Batangas"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5659","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5659_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4456-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Barrios Malabanan, Looc, Alangilan, Palsara, Makina, Magapi, Solis, Sampalukan, Calawit, and Balete, and the sitios of Sala, Paligawan, and Wani-Wani in the City of Lipa, are be separated from said city and constituted into a distinct and independent municipality, to be known as the Municipality of Balete, Province of Batangas. The seat of government of the new municipality shall be in the present site of Barrio Balete.\nUpon the approval of this Act, all the aforementioned sitios shall automatically be converted into barrios."}},{"id":"PH-H4456-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first mayor, vice-mayor, and councilors of the new municipality shall be elected in the next general elections for local officials."}},{"id":"PH-H4456-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon the qualification of the mayor, vice-mayor and councilors elected.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4457"] = {"id":"PH-H4457","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5660_1969.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Magallanes市","en":"An Act Creating the Municipality of Magallanes, Province of Agusan","orig":"An Act Creating the Municipality of Magallanes, Province of Agusan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5660","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5660_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4457-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Any provision of law to the contrary notwithstanding, there is hereby created in the Province of Agusan, a municipality to be known as the Municipality of Magallanes, which consists of a portion of the City of Butuan."}},{"id":"PH-H4457-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Municipality of Magallanes will comprise the territory beginning from a point Corner 1, a Bita-ug Tree, 2.00 meters in diameter located 10.00 meters, East from centerline of an existing Magallanes-Cabadbaran Road, thence due East, 4.112 kilometers to Corner 2; thence due South, 5.60 kilometers to Corner ,3; thence due West, 4.00 kilometers to Corner 4; which is the junction of Agusan and Cayucaman Rivers; thence following downstream along the East Bank of the Agusan River and along the Magallanes shores to Corner 5; thence due East, 97.00 meters to Corner 1, point of beginning, comprising the barrios of Magallanes and Calocan and the sitios of Dahican, Buhang, Popao, Cayucaman and Taod-oy, The seat of the government will be at the present barrio site of Magallanes."}},{"id":"PH-H4457-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The first mayor, vice-mayor and councilors shall be elected in the next general elections for local officials. All other officers and employees of the said municipality shall be appointed as provided for by law."}},{"id":"PH-H4457-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4458"] = {"id":"PH-H4458","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5661_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating the Municipality of Tampakan in the Province of South Cotabato","orig":"An Act Creating the Municipality of Tampakan in the Province of South Cotabato"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5661","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5661_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4458-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Barrios Tampakan, Maltana, Kipaldig, and Liberty and the sitios of Boto, Lambayong, Kolondatal, Tablo, Liberty II and Miasong in the Municipality of Tupi, Province of South Cotabato, are separated from the said municipality, and constituted into a distinct and independent municipality to be known as the Municipality of Tampakan, same province. The seat of government of the municipality shall be in the present site of Barrio Tampakan."}},{"id":"PH-H4458-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first mayor, vice-mayor and councilors of the new municipality shall be elected in a special election to coincide with the next general elections in nineteen hundred sixty-nine."}},{"id":"PH-H4458-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4459"] = {"id":"PH-H4459","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5662_1969.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating the Municipality of San Isidro in the Province of Bohol","orig":"An Act Creating the Municipality of San Isidro in the Province of Bohol"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5662","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5662_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4459-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Barrios Caimbang, Cansagus, Causwagan Sur and San Isidro in the Municipality of Catigbian, Province of Bohol; Barrios Abihilan, Banunos, Cambansag and Cansague in the Municipality of Antequera, same province; Barrios Masonoy and Candungao in the Municipality of Calape, same province; and Barrio Cabanugan in the Municipality of Tubigon, same province, are hereby separated from said municipalities and constituted into a distinct and independent municipality, to be known as the Municipality of San Isidro."}},{"id":"PH-H4459-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The seat of government of the new municipality shall be the present site of Barrio San Isidro mentioned in the preceding section."}},{"id":"PH-H4459-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The first mayor, vice-mayor and councilors of the new municipality shall be elected at the next general elections, to hold office until their successors shall have been elected in the next general elections for local officials and shall have qualified. The Municipality of San Isidro shall.begin to exist upon the election and qualification of the newly elected municipal officials."}},{"id":"PH-H4459-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Until otherwise provided by law, the new Municipality of San Isidro shall be considered a part of the second congressional district of the Province of Bohol."}},{"id":"PH-H4459-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"To provide the new Municipality of San Isidro with buildings to house the offices of its elective and appointive municipal officials, the Office of the President shall allocate and cause to be delivered, and erected or assembled at least nine units of the \"Marcos-type\" of prefabricated school buildings. The President may, however, in Ms discretion give from any available fund at his disposal the amount of one hundred thousand pesos instead of the prefabricated buildings herein provided."}},{"id":"PH-H4459-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4460"] = {"id":"PH-H4460","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5663_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Amending the Revised Charter of the City of Manila (Re Department of Social Welfare)","orig":"An Act Amending the Revised Charter of the City of Manila (Re Department of Social Welfare)"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5663","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5663_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4460-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section eighty-A of Republic Act Numbered Four hundred nine, otherwise known as the Revised Charter of the City of Manila, is hereby amended to read as; follows:\nSection 80-A. Department of Social Welfare. —There .shall be a Social Welfare Department which shall administer a comprehensive and integrated program of said services for the City of Manila and shall have the following general powers and duties:\n\"(a) He shall have control and supervision over the social services of the city;\n\"(b) He shall execute and enforce all laws, ordinances and regulations relating to social services;\n\"(c) He shall recommend to the municipal board the passage of ordinance as he deem necessary for the ren­dition of maximum social services to the city;\n\"(d) He shall cause to be prosecuted all violations of social service laws and ordinances;\n\"(e) He shall cooperate with all public and private relief agencies and charitable organizations in their missions to the city and shall be the representative of the Mayor to these agencies and organizations in matters affecting the social needs and services of the city; and \"(f) He shall exercise such other powers as may be necessary in the performance of his duties as the Social Welfare Officer of the city.\""}},{"id":"PH-H4460-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The same Act is hereby amended by inserting a new section between Section eighty-A and Section eighty-one which shall read as follows:\n\"Section 80-B. The Social Welfare Officer and Deputy Social Welfare Officer. —The department shall be headed by Social Welfare Officer who shall be assisted by a Deputy Social Welfare Officer and .such social service staff, technicians, and other personnel necessary to perform the functions of the Department.\n\"The Deputy Social Welfare Officer shall possess professional training in social work, with a master's degree in social work, a working knowledge of public administration, and must have had at least seven years of paid experience in executive and supervisory capacity in a social welfare agency, preferably in public agency. The incumbent assistant to the Social Welfare Officer possessing these qualifications shall continue in said position. The position shall be in the classified service and subject to Civil Service rules and regulations.\n\"Both officials shall receive an annual compensation at the rate fixed by law for the heads and assistant heads of the other city departments.\""}},{"id":"PH-H4460-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4461"] = {"id":"PH-H4461","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5664_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Amending Section Eighty-Eight of the Charter of the City of Silay (Re Separate School Division for the City)","orig":"An Act Amending Section Eighty-Eight of the Charter of the City of Silay (Re Separate School Division for the City)"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5664","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5664_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4461-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section eighty-eight of Republic Act Numbered Sixteen hundred twenty-one, otherwise known as the Charter of the City of Silay, as amended, is hereby further amended to read as follows:\n\"Section 88. The Bureau of Public Schools. —The Bureau of Public Schools shall exercise only supervisory power in respect to public schools in the City of Silay and the division superintendent of schools for the City of Silay shall have all the powers and duties in respect to the schools of the city as are vested in division superintendents in respect to schools of their divisions. The said superintendent shall be appointed and receive compensation in accordance with law.\""}},{"id":"PH-H4461-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4462"] = {"id":"PH-H4462","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5665_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for the Establishment of a National Trade School in the Municipality of San Rafael, Province of Bulacan, to Be Known as San Rafael National Trade School, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of a National Trade School in the Municipality of San Rafael, Province of Bulacan, to Be Known as San Rafael National Trade School, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["trade","education"],"docNumber":"Republic Act No. 5665","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5665_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4462-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Director of Vocational Education, a national trade school in the Municipality of San Rafael, Province of Bulacan, to be known as San Rafael National Trade School. Courses of secondary level shall be offered in said school."}},{"id":"PH-H4462-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said school during the fiscal year nineteen hundred seventy. Thereafter, such sum as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H4462-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4463"] = {"id":"PH-H4463","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5666_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for the Establishment of a National Trade School in the Municipality of San Jose Del Monte, Province of Bulacan, to Be Known as San Jose Del Monte National Trade School, and Authorizing The, Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of a National Trade School in the Municipality of San Jose Del Monte, Province of Bulacan, to Be Known as San Jose Del Monte National Trade School, and Authorizing The, Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["trade","education"],"docNumber":"Republic Act No. 5666","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5666_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4463-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the super­vision of the Director of Public Schools, a national trade school in the Municipality of San Jose del Monte, Province of Bulacan to be known as San Jose del Monte National Trade School. Courses of secondary level shall be offered in said school."}},{"id":"PH-H4463-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said school during the fiscal year nineteen hundred seventy. Thereafter, such sums as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H4463-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4464"] = {"id":"PH-H4464","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5667_1969.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for the Establishment of a School of Home Industries in the Municipality of Hinigaran, Province1 of Negros Occidental, to Be Known as Negros Occidental National Agro-Industrial School of Home Industries, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of a School of Home Industries in the Municipality of Hinigaran, Province1 of Negros Occidental, to Be Known as Negros Occidental National Agro-Industrial School of Home Industries, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5667","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5667_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4464-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Vocational Education, a school of home industries in Barrio Aranda in the Municipality of Hinigaran, Province of Negros Occidental, to be known as Negros Occidental National Agro-Industrial School of Home Industries. Comprehensive curriculum which includes both academic and industrial arts and handicraft courses shall be offered. The Secretary of Education is hereby empowered to organize the said school accordingly."}},{"id":"PH-H4464-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H4464-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of three hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said school during the fiscal year nineteen hundred and sixty-nine. Thereafter, such sums as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H4464-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4465"] = {"id":"PH-H4465","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5668_1969.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立San Jose市","en":"An Act Converting San Jose High School in the Municipality of San Jose, Province of Occidental Mindoro, Into a National School to Be Known as San Jose National High School, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Converting San Jose High School in the Municipality of San Jose, Province of Occidental Mindoro, Into a National School to Be Known as San Jose National High School, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5668","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5668_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4465-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"San Jose High School in the Municipality of San Jose, Province of Occidental Mindoro, is hereby converted into a national high school to be known as San Jose National High School General as well as vocational course shall be offered in said school."}},{"id":"PH-H4465-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education is hereby em­powered to reorganize said school accordingly."}},{"id":"PH-H4465-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of two hundred thousand pesos or so much thereof as may be necessary is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, to carry out the purposes of this Act during the fiscal year nineteen hundred and sixty-nine. Thereafter, such sums as may be needed for its annual operation shall be appropriated in the General Appropriations Act."}},{"id":"PH-H4465-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969.\nSat 02/18/2023"}}],"pack":"ph-p63"};
  FT["PH-H4466"] = {"id":"PH-H4466","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5669_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Sta市","en":"An Act Converting the Philippine Poultry School in the Municipality of Sta. Maria, Province of Bulacan, Into a National Agricultural School of Secondary and Collegiate Levels, Authorizing the Appropriation of Funds Therefor, and for Other Purposes","orig":"An Act Converting the Philippine Poultry School in the Municipality of Sta. Maria, Province of Bulacan, Into a National Agricultural School of Secondary and Collegiate Levels, Authorizing the Appropriation of Funds Therefor, and for Other Purposes"},"level":"law","status":"active","topics":["education","environment"],"docNumber":"Republic Act No. 5669","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5669_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4466-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Philippine Poultry School in the Municipality of Sta. Maria, Province of Bulacan, is hereby converted into a national agricultural school to be known as Sta. Maria Agricultural School. Said school shall be under the supervision of the Bureau of Vocational Schools and is hereby authorized to offer in its school curricula vocational, agricultural, and academic courses of. secondary as well as collegiate levels effective upon availability of funds."}},{"id":"PH-H4466-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of four hundred thousand pesos in addition to what is now provided is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of said Sta. Maria Agricultural School during the school year nineteen hundred seventy. Thereafter such sums as may be needed for the same purpose shall be included in the annual Appropriations Act."}},{"id":"PH-H4466-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969.\nSat 02/18/2023"}}],"pack":"ph-p63"};
  FT["PH-H4467"] = {"id":"PH-H4467","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5670_1969.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Camiling市","en":"An Act Establishing a School for Home Industries in the Municipality of Camiling, Province of Tarlac, and Authorizing the Appropriation of the Necessary Funds Therefor","orig":"An Act Establishing a School for Home Industries in the Municipality of Camiling, Province of Tarlac, and Authorizing the Appropriation of the Necessary Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5670","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5670_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4467-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established under the supervision and administration of the Home Industries Division of the Bureau of Vocational Education a vocational high school for home industries in the Municipality of Camiling, Province of Tarlac, to be known as the Sinilian Vocational High School for Home Industries."}},{"id":"PH-H4467-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education is hereby authorized to determine its administration and to organize the curricular instruction therein."}},{"id":"PH-H4467-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The school shall have the following functions:\na. Give home industries training to all people who wish to avail themselves at all times of the year of the facilities of the school.\nb. Study the efficient utilization of clay deposits, bamboos, and other abundant raw materials in the area for craft production.\nc. Conduct researches on designing and processing of clay, bamboo and other indigenous materials; make small hand tools and machines for training in skills and production.\nd. Undertake standardization of ceramic and other craft products.\ne. Give training in the production and marketing of ceramics, and other handicraft articles.\nf. Render consultant service in the chemistry and technology side of ceramic and craft production.\ng. Give extension training in the barrios and other towns or service area of the province."}},{"id":"PH-H4467-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The sum of fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation, and maintenance of the Sinilian Vocational High School for Home Industries during the fiscal year nineteen hundred sixty-eight-sixty-nine. Thereafter, such sum as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H4467-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4468"] = {"id":"PH-H4468","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5671_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of La Rioja Elementary School in the Municipality of Patnongon, Province of Antique, to Teofista M. Salvani Community School","orig":"An Act Changing the Name of La Rioja Elementary School in the Municipality of Patnongon, Province of Antique, to Teofista M. Salvani Community School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5671","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5671_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4468-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of La Rioja Elementary School in the Municipality of Patnongon, Province of Antique, is hereby changed to Teofista M. Salvani Community School."}},{"id":"PH-H4468-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4469"] = {"id":"PH-H4469","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5672_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Amending Republic Act Numbered Sixteen Hundred Twenty-Nine (Re Quezon Memorial Hospital School of Nursing)","orig":"An Act Amending Republic Act Numbered Sixteen Hundred Twenty-Nine (Re Quezon Memorial Hospital School of Nursing)"},"level":"law","status":"active","topics":["education","health"],"docNumber":"Republic Act No. 5672","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5672_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4469-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Six­teen hundred twenty-nine is amended to read as follows:\n\"Section 1. There shall be established a School of Nursing in the Quezon Memorial Hospital in the City of Lucena. The establishment, maintenance and operation of the said school of nursing shall be under the control and management of the Director of the said Quezon Memorial Hospital, subject to the executive supervision of the Secretary of Health.\""}},{"id":"PH-H4469-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section two of the same Act is amended to read as follows:\n\"Section 2. The sum of one hundred fifty thousand pesos: is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, maintenance and operation of the school of nursing for the fiscal year ending June thirty, nineteen hundred sixty-nine. Such sums as may be necessary for the operating expenses of the Quezon Memorial Hospital School of Nursing in succeeding fiscal years shall be included in subsequent General Appropriations Acts, which shall be disbursed by the School of Nursing authorities concerned, in accordance with the provisions of Commonwealth Act Numbered Two hundred forty-six, as amended.\""}},{"id":"PH-H4469-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4470"] = {"id":"PH-H4470","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5673_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating the Positions of Three Registers of Deeds for the Province of Cotabato, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Creating the Positions of Three Registers of Deeds for the Province of Cotabato, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5673","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5673_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4470-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Any provisions of law to the contrary notwithstanding, there shall be created the positions of three Registers of Deeds for the Province of Cotabato. One Register of Deeds shall serve the territory which includes the municipalities of Nuling, Parang, Buldon, Pigcawayan, Libungan, Midsayap, Pikit, Pagalungan, Kabacan, Carmen, Matalam, Magpot, Kidapawan and Makilala; the second, the territory which includes the municipalities of Mlang, Tulunan, Columbio, Buluan, Tacurong, Sultan Sa Barongis, Isulan, Ampatuan, Maganoy, Datu Piang, Tumbao, Dinaig, Upi, Lebak, Kalamansig and Palimbang; and the third, the territory which includes the municipalities of Norala, Surala, Banga, Tantangan, Koronadal, Tupi, Polomolok, General Santos, Kiamba, Maitum, Maasin, Tampacan and Glan, all in the Province of Cotabato."}},{"id":"PH-H4470-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of the said offices for the fiscal year nineteen hundred seventy. Thereafter, such sums as may be needed for its operation and maintenance shall be included in the annual General Appro­priations Act."}},{"id":"PH-H4470-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4471"] = {"id":"PH-H4471","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5674_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Batac市","en":"An Act Creating a Branch Office of the Register of Deeds of the Province of Ilocos Norte, \"With Permanent Station At the Municipality of Batac, Same Province, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Creating a Branch Office of the Register of Deeds of the Province of Ilocos Norte, \"With Permanent Station At the Municipality of Batac, Same Province, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5674","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5674_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4471-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby created a branch office of the Register of Deeds of the Province of Ilocos Norte, with permanent station at the Municipality of Batac, same province, which shall perform all the duties and functions of the register of deeds for the Municipalities of Batac, Paoay, Currimao, Pinili, Badoc, Espiritu, Marcos, Nueva Era, Dingras and Solsona, all in the Province of Ilocos Norte."}},{"id":"PH-H4471-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"To carry out the provisions of this Act, there is hereby authorized to be appropriated for the fiscal year nineteen hundred seventy, out of any funds in the National Treasury not otherwise appropriated, the sum of twenty thousand seven hundred eighty-four pesos to be spent for the following:\na. Deputy Register of Deeds.............................................................\n₱5,112.00\nb. One supervising clerk....................................................................\n3,300.00\nc. One senior cash clerk....................................................................\n2,424.00\nd. One clerk.......................................................................................\n2,196.00\ne. One messenger.............................................................................\n1,800.00\nf. One janitor......................................................................................\n1,476.00\ng. One laborer...................................................................................\n₱l,476.00\nh. Sundry expenses..........................................................................\n3,000.00 Such sums as may be necessary for the same purpose in subsequent years shall be included in the annual General Appropriations Act."}},{"id":"PH-H4471-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4472"] = {"id":"PH-H4472","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5675_1969.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Placing the Subprovince of Apayao Under the Jurisdiction of the Court of First Instance of Mountain Province, Amending for the Purpose Sections Fifty, Fifty-Two and Fifty-Four of the Judiciary Act of 1948","orig":"An Act Placing the Subprovince of Apayao Under the Jurisdiction of the Court of First Instance of Mountain Province, Amending for the Purpose Sections Fifty, Fifty-Two and Fifty-Four of the Judiciary Act of 1948"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 5675","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5675_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4472-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The first paragraph of Section fifty of Republic Act Numbered Two hundred ninety-six, otherwise known as the Judiciary Act of 1948, as amended, is further amended to read as follows:\n\"Ten judges shall be commissioned for the First Judicial District. Four judges shall preside over the Courts of First Instance of Cagayan and Batanes, and shall be known as judges of the first, second, third and fourth branches thereof, respectively, the judge of the second branch to preside also over the Court of First Instance of Batanes; four judges shall preside over the Court of First Instance of Isabela, and shall be known as the judges of the first, second, third and fourth branches thereof; and two judges shall preside over the Court of First Instance of Nueva Vizcaya, to be known as the judges of the first and second branches thereof.\""}},{"id":"PH-H4472-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The third paragraph of Section fifty-two of the same Act, as amended, is further amended to read as follows :\n\"For the first Judicial District, the judge of the first branch of the Court of First Instance of Cagayan and Batanes shall be stationed in the Municipality of Tuguegarao, Province of Cagayan; the judge of the second branch, in the Municipality of Aparri, same province; the judge of the third branch, in the Municipality of Sanchez Mira, same province; and the judge of the fourth branch, in the Municipality of Tuao, same province; one judge shall be stationed in the Municipality of Hagan, Province of Isabela, one judge shall be stationed in the Municipality of Cabagan, same province; one judge shall be stationed at Cauayan, same province; the judge of the fourth branch shall be stationed in the Municipality of Roxas, same province; and two judges, in the Municipality of Bayombong, Province of Nueva Vizcaya.\""}},{"id":"PH-H4472-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The fourth paragraph of Section fifty-four of the same Act, as amended, is further amended to read as follows:\n\"Second Judicial District: Whenever the interest of justice so requires, a special term of court shall be held at Lubuagan, Subprovince of Kalinga; and the Kalinga branch at Tabuk, Subprovince of Kalinga to hold court at Kabugao, Subprovinee of Apayao on the first Tuesday of February of each year.\""}},{"id":"PH-H4472-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4473"] = {"id":"PH-H4473","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5676_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"The Revised Barrio Charter","orig":"An Act Clarifying the Scope and Applicability of Republic Act Numbered Thirty-Five Hundred and Ninety, Otherwise Known as \"The Revised Barrio Charter\", Amending for the Purpose Section Twenty-Six Thereof"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5676","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5676_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4473-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section twenty-six of Republic Act Numbered Thirty-five hundred and ninety, otherwise known as \"The Revised Barrio Charter\", is hereby amended to read as follows:\n\"Section 26. Extent of applicability —Notwithstanding the provisions of any city charter to the contrary, the foregoing provisions shall be made applicable only to such barrios within the jurisdiction of chartered cities as were existing before the enactment of this Act: Provided, however, That nothing in this Act shall be interpreted as abolishing any barrio existing in chartered cities before the enactment of this Act.\""}},{"id":"PH-H4473-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall have retroactive effect as of the twenty-second day of June, nineteen hundred and sixty- three.\nApproved, June 21,1969."}}],"pack":"ph-p63"};
  FT["PH-H4474"] = {"id":"PH-H4474","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5677_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"对《采矿工程法 .》的修改","en":"Mining Engineering Law of the Philippines.","orig":"An Act Amending Section Nineteen of Republic Act Numbered Forty-Two Hundred Seventy-Four, Otherwise Known as the \"Mining Engineering Law of the Philippines.\""},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 5677","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5677_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4474-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The first paragraph of Section nineteen of Republic Act Numbered Forty-two hundred seventy-four is hereby amended to read as follows:\n\"Section 19. Issuance of Certificates. -The Board of Examiners for Mining Engineers shall, within two years only after the approval of this amendatory Act, receive applications for certificate of registration without examination as mining engineer, and may issue to any applicant who, on the date of approval of this Act, is:\""}},{"id":"PH-H4474-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4475"] = {"id":"PH-H4475","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5678_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Amending Item 34, Page 95, Subparagraph 24, for the Province of Isabela, Paragraph \"A\", Title B, Section One of Republic Act Numbered Thirty-One Hundred One (Re Public Works Projects for the Province of Isabela)","orig":"An Act Amending Item 34, Page 95, Subparagraph 24, for the Province of Isabela, Paragraph \"A\", Title B, Section One of Republic Act Numbered Thirty-One Hundred One (Re Public Works Projects for the Province of Isabela)"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5678","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5678_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4475-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Item 34, page 95, subparagraph 24, for the Province of Isabela, paragraph \"a\", Title B, Section one of Republic Act Numbered Thirty-one hundred one is hereby amended to read as follows:\n\"34. Masigun Bridge, (Masigun Creek), Burgos cons­truction 40,000.00\""}},{"id":"PH-H4475-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4476"] = {"id":"PH-H4476","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5679_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Establishing a Filipino War Memorial and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing a Filipino War Memorial and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5679","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5679_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4476-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of one million pesos for the establishment of a Filipino War Memorial at the Government Center in Quezon City or wherever the President of the Philippines shall deem it proper to establish, so as to house the relics, documentary and photographic records, paintings, the weapons and ammunition used in war, as well as models, statues and other war memorials."}},{"id":"PH-H4476-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4477"] = {"id":"PH-H4477","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5680_1969.html","fetchedAt":"2026-10-06","articleCount":28,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating the Board of Examiners for Physical Therapists and Occupational Therapists","orig":"An Act Creating the Board of Examiners for Physical Therapists and Occupational Therapists"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5680","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 28 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5680_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4477-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short title of Act -This Act shall be known | as the Philippine Physical and Occupational Therapy Law."}},{"id":"PH-H4477-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Definition of Terms. -As used in this Act, the following terms shall mean:\na. Physical therapy is the art and science of treatment by means of therapeutic exercises, heat, cold, light, water, manual manipulation, electricity, and other physical agents.\nb. Physical therapy technician is a person, who not having acquired a bachelor's degree in Physical Therapy is qualified through in service training and practical experience to assist in the application of physiotherapeutic procedures and to undertake specific assignments as directed by a qualified physical therapist in carrying out the prescription of a licensed physician. Such, assignments shall be confined within the limits of a hospital or institution of employment.\nc. Rehabilitation medicine, at the patient level, is the \"clinical management of the problems associated with disability, with the objective of improving to the maximum level the physical, socio-economic and physiological functioning of a disabled individual. Medical rehabilitation is an integral part of total medical care. Total rehabilitation is best achieved through the coordinated work of various health disciplines like medicine, psychology, social work, physical therapy, occupational therapy, speech and hearing, nursing, vocational evaluation, dietetics, and special education.\"\nd. Physical therapist is a person legally qualified and licensed to practice physical therapy under this Act.\ne. Physiatrist is a legally qualified and licensed physician specializing in the practice of rehabilitation medicine.\nf. Occupational therapy is a paramedical discipline concerned with the administration of medically prescribed treatment, in the form of supervised activity, to persons disabled by disease or injury. The objective of occupational therapy is to contribute to the development of the disabled person's independence, to improve his emotional, social, and physical well-being and his ability to care for himself both at home and on the job, and to begin early evaluations and experimentation for future job training and employment.\nOccupational therapy may be prescribed by a general medical practitioner or a specialist in any of the recognized branches of medicine and is administered under the direction of a registered occupational therapist.\ng. Occupational therapist is a legally qualified person licensed to practice occupational therapy under this Act and who by accepted academic training and professional clinical experience possesses the knowledge and skills to achieve the objectives as defined and set by the occupational therapy profession. The occupational therapist functions through the use of the basic methods, approaches and procedures of occupational therapy (creative, manipulative, educational, prevocational evaluation and self-care activities) which are designed to assess and develop the actual and potential abilities of the individual.\nThe occupational therapist plans, organizes, evaluates, and participates in a medically oriented treatment program to assist the disabled person towards physical independence, productivity, and constructive personal or social relationship.\nThe occupational therapist functions in general and special hospitals, rehabilitation and welfare centers, pediatric clinics, psychiatric clinics, specialized schools, geriatric institutions, home care programs, and work-adjustment units.\nh. Occupational therapy technician or assistant is a person who, not having acquired a bachelor's degree in occupational therapy, is qualified, as determined by a bona fide national professional association of occupational therapists in the Philippines through in service training and practical experience, to function as an assistant to and under the direct supervision of an occupational therapist to assist in rehabilitating patients in hospitals and similar institutions.\ni. Disability is a loss or reduction of a person's capacity to effectively cope with the demands of his environment as a result of disease or injury, including birth trauma."}},{"id":"PH-H4477-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Board of Examiners for Physical Therapists and Occupational Therapists. -There is hereby created a Board of Examiners for Physical Therapists and Occupational Therapists, hereinafter called the Board, to be composed of a chairman and four members who shall be appointed by the President of the Philippines with the consent of the Commission on Appointments. The chairman shall be a physiatrist and four members shall be two professionally qualified occupational therapists and two professionally qualified physical therapists. The physiatrist shall be appointed from lists of qualified physiatrists, submitted by the society of physical medicine and rehabilitation and the occupational therapists and physical therapists by their respective bona fide national professional organization or association and submitted to the President of the Philippines through the Commissioner of Civil Service. Succeeding Boards shall consist of a chairman who shall be a physiatrist recommended and appointed as hereinabove stated, two members who shall be registered physical therapists recommended by the Philippine Physical Therapy Association, and two members who shall be registered occupational therapists who shall be recommended by the Occupational Therapy Association of the Philippines, Incorporated. The chairman and members of the Board shall be appointed within six months from the approval of this Act."}},{"id":"PH-H4477-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Qualifications of Board Members - The chairman and members of the Board, at the time of their appointment, shall each be:\na. A citizen and resident of the Philippines for at least five years;\nb. At least thirty-five years of age if he is a chairman, or thirty years of age if he is a member;\nc. Of good moral character and must not have been convicted of a crime involving moral turpitude;\nd. A physiatrist if he is the chairman, or a holder of a bachelor's degree in physical therapy or occupational therapy with at least five years experience as a physical therapist or occupational therapist as the case may be; and\ne. Not a member of the faculty of any school, college or university conferring a bachelor's degree in physical therapy or occupational therapy as a major study at the time of his appointment nor have any pecuniary interest, directly or indirectly, in any such institution: Provided, That this subparagraph shall not be applicable to the chairman and members of the first Board."}},{"id":"PH-H4477-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Powers and Duties of the Board. -The Board shall have the following powers and duties:\na. To issue, suspend, revoke, or re-issue any certificate of registration for the practice of physical therapy or occupational therapy as defined in this Act;\nb. To study, promote and improve the conditions of the practice of physical therapy and occupational therapy in the Philippines;\nc. To give examinations to applicants for the practice of physical therapy and occupational therapy in accordance with the provisions of this Act;\nd. To look into the conditions affecting the practice of physical therapy and occupational therapy in the Philippines and, whenever necessary, adopt such measures as may be proper for the maintenance of good ethics and high professional standard in the practice of such professions ;\ne. To study the condition affecting physical therapy and occupational therapy education; to study and examine the facilities and prescribe the basic curricula of any school, college or university seeking permission to open or offering physical therapy or occupational therapy program or course; and to require the employment of qualified members of the faculty in such educational institutions. No school, college or university shall be authorized to offer courses in physical therapy or occupational therapy without the favorable written recommendation of the Board;\nf. To exercise such other powers, functions and duties as may be necessary to carry into effect the purposes of this Act and to maintain an efficient, ethical, moral and professional standard in the practice of physical and occupational therapy in the Philippines."}},{"id":"PH-H4477-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Office of Board Members. -The chairman and members of the Board shall hold office for a term of three years and until their successors shall have been appointed and qualified: Provided, That of the first Board, two members, a physical therapist and an occupational therapist, shall hold office for a term of two years and. the other two members belonging to the same two professions shall hold office for a term of three years. Any vacancy in the Board for any cause other than the expiration of the term shall be filled by appointment until the expiration of the term of the member to be replaced."}},{"id":"PH-H4477-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Removal of Members: -Any member of the Board may be removed by the President of the Philippines for neglect of duty, incompetence, malpractice, or unprofessional, unethical, immoral or dishonorable conduct after having been given the opportunity to defend himself in a proper administrative investigation: Provided, That pending the final disposition of the case against him, a member may be suspended by the President and another appointed to fill the temporary vacancy in the Board."}},{"id":"PH-H4477-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Executive Officer of the Board. -The Commissioner of Civil Service shall be the executive officer of the Board, and shall conduct the examination given by it according to the rules and regulations promulgated by him and approved by the President. The Secretary of the Board of Examiners appointed in accordance with Section ten of Republic Act Numbered Four thousand seven, as amended, shall be the Secretary of the Board. All records of administrative proceedings and investigations of the Board shall be kept by the Civil Service Commission.\nThe Secretary of the Board shall keep separate registers of all persons to whom certificates of registration for the practice of physical therapy and occupational therapy, respectively, have been issued. Such registers shall contain the name and sex of the physical therapist or the occupational therapist registered therein and the name of the school, college or university from which he graduated or in which he studied. He shall keep such registers up to date."}},{"id":"PH-H4477-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Compensation of Board Members. -The members of the Board shall each receive as compensation the sum of ten pesos for each applicant examined. Any member of the Board who is in the service of the Government shall receive the compensation herein provided in addition to his salary."}},{"id":"PH-H4477-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Bides and Regulations. -Subject to approval of the President of the Philippines and with the advice of the Commissioner of Civil Service, the Board shall adopt rules and regulations to carry out the provisions of this Act and shall set ethical and professional standards for the practice of physical therapy and occupational therapy in the Philippines."}},{"id":"PH-H4477-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Annual Report. -The Board shall submit an annual report to the President of the Philippines and the President of the Senate and Speaker of the House of Representatives after the close of each fiscal year, giving a detailed account of the proceedings of the Board during the year and embodying such recommendations as the Board may desire to make."}},{"id":"PH-H4477-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Inhibition Against the Practice of Physical, Therapy and Occupational Therapy. -No person shall practice or offer to practice physical therapy or occupational therapy in the Philippines as defined in this Act, without the prescription of a duly registered physician and a valid certificate of registration as a physical therapist or an occupational therapist, as the case may be, issued by the Board of Examiners for Physical Therapists and Occupational Therapists.\nA person shall be deemed to be practicing physical therapy within the meaning of this Act, who for a fee or other consideration applies or advises the use of heat, cold, light, electricity or other means for the treatment or prevention of disorders of neuro-muscular or musculo-skeletal systems of the human body or subject a patient to passive mobilization or physical rehabilitation procedures repeatedly.\nA person shall be deemed to be practicing occupational therapy within the meaning of this Act who, for a fee or other consideration, applies or advises the use of occupational therapy treatment media as herein defined, or other occupational means for the treatment or prevention of disorders of the physical or psychological formation of the human body, or subjects a patient to occupational therapy procedures repeatedly."}},{"id":"PH-H4477-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Exemptions. -Nothing in this Act shall be construed to apply or affect the practice of (a) any registered physician; (b) any physical therapy or occupational therapy student as part of their undergraduate training in an approved school, college or university for physical therapy or occupational therapy, as the case may be; (c) all physical therapists who are already in the government service who became eligible by virtue of the testimonial examination given by the Civil Service Commission on December twenty-nine, nineteen hundred and sixty-seven in the City of Manila."}},{"id":"PH-H4477-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Holding of Examinations. -Except as otherwise specifically provided, all applicants for registration for the practice of physical therapy in the Philippines shall be given by the Board on the first .Saturday of June and December of each year, and for the practice of occupational therapy one week thereafter, at the City of Manila or at such other places as may be deemed necessary or expedient by the Board, subject to the approval of the Commissioner of Civil Service and the President of the Philippines."}},{"id":"PH-H4477-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Qualification of Applicants. -In order to be admitted to the physical therapists' examination or the occupational therapists' examination, as the case may be, an applicant must, at the time of the filing of his or her application, establish to the satisfaction of the Board that:\na. He is a citizen of the Philippines, or if a foreigner, must prove that the country of which he is a subject or citizen permits Filipino physical therapists or occupational therapists to practice within its territorial jurisdiction on the same basis as the subjects or citizens of such country;\nb. He is at least twenty-one years of age;\nc. He is of good health and of good moral character;\nd. He has finished a standard academic high school course or its equivalent in a school, college or university legally established or duly recognized by the government;\ne. He has received a degree, if he is an applicant for the physical therapy examination, in Physical Therapy from a school of physical therapy duly recognized by the Government: Provided, That such educational institution offers at least the following academic subjects prior to the admission in the main, physical therapy course, namely, English, Mathematics, Speech, Political Science Social Science, Humanities, Psychology, Spanish, Physics, Zoology and Chemistry: Provided, further, That such educational institution offers at least the following academic subjects in the main therapy course, namely: Anatomy, Physiology, Applied Kinesiology, Introduction to Nursing, Theory and Practice of Massage, Electrotherapy, Prosthetics, Splinting, Bandaging and Plasterwork, Exercise Therapy, General Medical and Surgical Conditions, Neurological and Orthopedic Conditions, Principles of Rehabilitation, Pathology, Proprioceptive Neuromuscular Facilitation, Selected Medical and Surgical Conditions, Administration and Ethics, Medical Psychology; or He has received a degree, if he is an applicant for the occupational therapy examination, in Occupational Therapy or any other title of equivalent standard from a school of occupational therapy duly recognized by the Government: Provided, That such educational institution offers at least the following academic subjects prior to admission in the main occupational therapy course, namely, English, Spanish, Humanities, Zoology, Chemistry, Sociology, Philippine History and Works of Rizal, Mathematics: Provided, further, That such educational institution offers at least the following academic subjects in the main occupational therapy course, namely, Biological Sciences consisting of Human Anatomy and Physiology, Neuro-anatomy and Neurophysiology, and Kinesiology (Principles of Human Motion) ; Behavioral Sciences consisting of Human Development, Personality Development, Group Processes, Interpersonal and Interprofessional Relationships; Physical and Psychological Dysfunction Basic, General Pathology subjects including General and Medical Conditions, Neurological and Orthopedic Conditions, Pediatrics and Psychiatry; Occupational Therapy Skills consisting of Creative and Manual Arts, Vocational and Avocational Activities, Daily Living Skills and Teaching Techniques; Occupational Therapy Orientation Evaluation and Treatment, Principles of Physical and Psychosocial Dysfunctions consisting of Organization and Administration, General Medical and Surgical Conditions, Neurological and Orthopedic Conditions, Psychology, Prevocational;\nf. He has completed at least nine months of internship in Physical Therapy in an adequate Physical Therapy Department of a hospital or clinic as certified by the Department of Health; or has at least nine months clinical experience under the supervision of a competent and duly registered occupational therapist in an accredited hospital or institution, as the ease may be. Clinical experience shall include the effective treatment of psychosocial and physical dysfunctions of patients of wide age range and of both sexes."}},{"id":"PH-H4477-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Scope of Examination. -The examinations for the practice of physical therapy and occupational therapy in the Philippines shall consist of written and practical examinations of the scope which shall be determined by the Board, taking into consideration the teaching plan of the schools legally constituted in the Philippines. It shall be the duty of the Board to prepare the schedule of subjects mentioned in subparagraph (e) of the preceding section of this Act, as well as practical and clinical examinations of all candidates, and to submit the same to the President of the Philippines for approval through the Commissioner of Civil Service, and to publish the same as approved at least two months before the date of the examination wherein such subjects are to be used. Any alteration or amendment that may be made in the schedule of subjects shall likewise be approved by the President."}},{"id":"PH-H4477-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Ratings in the Examination. -In order to pass the first examination, a candidate must obtain a general rating of not below seventy-five per cent in the written examination with no rating below sixty per cent. Any applicant who failed in the first examination but obtained seventy-five per cent in each of at least five of the subjects may be permitted to take a second examination within one year from the date of the first examination. In order to pass in the second examination, the examinee must obtain a rating of not below seventy-five per cent in each of the subjects repeated: Provided, That an, applicant who failed in the set of subjects repeated in the second examination must take a re-examination in all the subjects within one year from the date of the second examination: Provided, further, That should he still fail in the third re-examination, the applicant shall be required to undertake a prescribed course of study and to show proof of the completion of such course before he will be admitted to the fourth examination."}},{"id":"PH-H4477-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Report of the Results of the Examinations. - The Board of Examiners for Physical Therapists and Occupational Therapists shall, within one hundred twenty days after each examination, report the ratings obtained by each candidate to the Commissioner of Civil Service, who shall, with his recommendation, submit such ratings to the President for his approval."}},{"id":"PH-H4477-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Issuance of Certificates. -Certificates of registration as physical therapist or occupational therapist shall be issued to any applicant who passes the respective examination after approval of his ratings by the President of the Philippines and upon payment of the required fees. Every certificate of registration shall show the full name of the registrant, have a serial number, bear the signatures of the members of the Board attested by the Secretary of the Board and duly authenticated by the seal of the Board of Examiners for Physical Therapists and Occupational Therapists.\nThe issuance of certificate of registration by the Board to the registrant shall evidence that the person named therein is entitled to all rights and privileges of a registered physical therapist or a registered occupational therapist, as the case may be, until the said certificate for just cause, is revoked temporarily or cancelled. For all intents and purposes of this Act the members of the first Board shall be considered as having duly qualified and registered as occupational therapists and physical therapists as the case may be."}},{"id":"PH-H4477-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Initial -The initials PTRP and OTRP, which stands for Physical Therapist Registered, Philippines and Occupational Therapist Registered, Philippines, may be added after the name of the physical therapist or occupational therapist, as the case may be, who successfully passes the examination given by the Board."}},{"id":"PH-H4477-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Registration by reciprocity. -Any physical therapist, physiatrist or occupational therapist holding valid certificate of registration issued under the laws of a foreign country may practice his profession in the Philippines without passing an examination given by the Board if the requirements for the registration and licensing of a physical therapist, physiatrist or occupational therapist in such foreign country are substantially the same as those provided for in this Act and that the laws of such country or state grant the same privileges to physical therapists, physiatrists and occupational therapists registered in the Philippines on the same basis as the subjects or citizens of such foreign country or state."}},{"id":"PH-H4477-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Examination and Registration Fees. -Applicants for examination for the profession of physical therapy or occupational therapy shall pay an examination fee of twenty-five pesos each. Successful applicants shall pay a registration fee of ten pesos each."}},{"id":"PH-H4477-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Refusal to Issue Certificate in Certain Cases. - The Board of Examiners for Physical Therapists and Occupational Therapists shall not issue a certificate of registration to any person convicted of any criminal offense involving moral turpitude by a court of competent jurisdiction, and to any person guilty of illegal practice, unethical advertising, or other immoral or dishonorable conduct. The Board shall give the applicant a written statement of the reason or reasons for its action, which statement shall be incorporated in the records of this Board."}},{"id":"PH-H4477-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Re-issuance of Revoked Certificate and Replacement of Lost Certificate. -The Board may, for reason of equity and justice and upon proper application therefor, issue another copy, original or duplicate, upon the payment of ten pesos, of a certificate which has been revoked. A new certificate of registration to replace a lost, destroyed or mutilated certificate may be issued subject to the rules of the Board and upon the payment of ten pesos."}},{"id":"PH-H4477-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Professional Licenses Fee. -A registered physical therapist or occupational therapist shall pay a professional license fee of fifty pesos per annum, payable annually or semi-annually."}},{"id":"PH-H4477-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"All laws, parts of laws, orders, or ordinances, or regulations in conflict with the provisions of this Act pertaining to physical or occupational therapeutic duty and practice shall be, and are hereby repealed."}},{"id":"PH-H4477-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Prohibition in the Practice of Physical Therapy or Occupational Therapy; Penalty.Any person who shall practice physical therapy or occupational therapy in the Philippines within the meaning of this Act, without a valid certificate of registration issued by the Board of Examiners for Physical Therapists and Occupational Therapists, or any person presenting as his or her own the certificate of another, or any person giving any false or forged evidence to the Board in order to obtain a certificate of registration or admission to an examination, or any person assuming or advertising himself or herself as a registered physical therapist or registered occupational therapist, or any person violating any provision of this Act shall be guilty of a misdemeanor and shall, upon conviction, be sentenced to pay a fine of not less than one thousand pesos nor more than five thousand pesos or to suffer imprisonment for a period of not less than one year nor more than five years, or both such fine and imprisonment at the discretion of the Court."}},{"id":"PH-H4477-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4478"] = {"id":"PH-H4478","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5681_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating Two Additional Positions of Assistant Provincial Fiscal for the Province of Davao Del Norte, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","orig":"An Act Creating Two Additional Positions of Assistant Provincial Fiscal for the Province of Davao Del Norte, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 5681","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5681_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4478-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The provision of Section sixteen hundred seventy-four of the Administrative Code, as amended, relative to the number of assistant provincial fiscals in the Province of Davao del Norte, is further amended to read as follows:\n\"Davao del Norte, five assistant provincial fiscals;\""}},{"id":"PH-H4478-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"There is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of twenty thousand pesos or so much thereof as may be necessary to pay the share of the National Government for the positions provided for in this Act for the current fiscal year. Thereafter, appropriations for the succeeding fiscal years shall be included in the annual General Appropriations Act,"}},{"id":"PH-H4478-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4479"] = {"id":"PH-H4479","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5682_1969.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Designation of the Lieutenant-Governor to Governor of the Sub-Province of Guimaras, Province of Iloilo, and Creating in Said Sub-Province the Positions of Fiscal and Division Superintendent of Schools","orig":"An Act Changing the Designation of the Lieutenant-Governor to Governor of the Sub-Province of Guimaras, Province of Iloilo, and Creating in Said Sub-Province the Positions of Fiscal and Division Superintendent of Schools"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5682","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5682_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4479-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Effective upon the approval of this Act, the lieutenant-governor of the Sub-province of Guimaras, Province of Iloilo, shall henceforth be called Governor and shall exercise all executive powers vested under existing laws in a provincial governor."}},{"id":"PH-H4479-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Ninety per centum of all provincial taxes, fines or other revenues collected in the Sub-province of Guimaras or by reason of any right originating therein shall accrue to the treasury of said sub-province for the sole use and benefit thereof. The remaining ten per centum of such collections shall accrue to the general fund of the province: Provided, however, That the collections belonging to the road tax shall accrue in their entirety to the treasury of said sub-province."}},{"id":"PH-H4479-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"There are hereby created the positions of fiscal and division superintendent of schools in the Sub-province of Guimaras, which offices shall be organized within thirty days from the approval of this Act. Appointment to the position of fiscal shall be made in accordance with existing laws except the division superintendent of schools who shall be appointed as hereafter provided, and the appointees thereof shall exercise such powers and perform such duties as are vested in the office by law as if the sub-province of Guimaras were a different and separate province with their seat of office in the capital of the sub-province. Within thirty days after the approval of this Act, the offices herein created shall be provided with their corresponding clerks and other necessary helps by the Provincial Board of Iloilo. The division superintendent of schools shall be appointed by the President of the Philippines with the consent of the Commission on Appointments, provided that the appointee shall be a holder of the degree of Master of Arts and shall have no less than fifteen years of actual official connection with the Philippine public elementary school system, at least five years of which shall be in a supervisory capacity."}},{"id":"PH-H4479-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All Acts, executive orders and rules and regula­tions inconsistent with the provisions of this Act are hereby repealed or amended accordingly."}},{"id":"PH-H4479-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4480"] = {"id":"PH-H4480","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5683_1969.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting Feliciano Yu a Franchise for An Electric Light, Heat and Power System in the Municipality of San Isidro, Province of Davao Oriental","orig":"An Act Granting Feliciano Yu a Franchise for An Electric Light, Heat and Power System in the Municipality of San Isidro, Province of Davao Oriental"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5683","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5683_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4480-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two and to the provisions of the Constitution, there is granted to Feliciano Yu, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat and/or power for sale within the Municipality of San Isidro, Province of Davao Oriental; Provided, That the franchise holder shall extend service to all the areas covered by the franchise, particularly the barrios therein, within five years from the commencement of service; and any area not served within the said period shall be deemed excluded from this franchise."}},{"id":"PH-H4480-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the latter is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H4480-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that in the event the Government should desire to maintain and operate for itself, the system and enterprise herein authorized, the grantee shall surrender his franchise and turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H4480-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without Executive approval, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4481"] = {"id":"PH-H4481","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5684_1969.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting Mati Light and Power, Inc. a Franchise for An Electric Light, Heat and Power System in the Municipality of Mati, Province of Davao Oriental","orig":"An Act Granting Mati Light and Power, Inc. a Franchise for An Electric Light, Heat and Power System in the Municipality of Mati, Province of Davao Oriental"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5684","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5684_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4481-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to Mati Light and Power, Inc., for a period of twenty-five years from the approval of this. Act, the right, privilege and authority to construct, maintain and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat and power for sale within the Municipality of Mati, Province of Davao Oriental, Philippines."}},{"id":"PH-H4481-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the Natoinal Power Corporation electric heat and power, the latter is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H4481-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that in the event the Government should desire to maintain and operate for itself the system and enterprise herein authorized, the. grantee shall surrender its franchise and turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H4481-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"In consideration of this franchise the grantee shall pay a tax equivalent to five percent of its gross income."}},{"id":"PH-H4481-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without Executive approval, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4482"] = {"id":"PH-H4482","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5685_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Authorizing Marcelina S. Aquino to Transfer, Assign, Sell or Mortgage in Favor of Any Banking or Financing Institution Her Franchises Under Republic Acts Numbered Six Hundred Ninety-Seven and Seven Hundred Fifty-Seven, to Install, Operate and Maintain Telephone Systems in the City of Butuan and in the Province of Agusan and the Municipalities and Municipal Districts Thereof","orig":"An Act Authorizing Marcelina S. Aquino to Transfer, Assign, Sell or Mortgage in Favor of Any Banking or Financing Institution Her Franchises Under Republic Acts Numbered Six Hundred Ninety-Seven and Seven Hundred Fifty-Seven, to Install, Operate and Maintain Telephone Systems in the City of Butuan and in the Province of Agusan and the Municipalities and Municipal Districts Thereof"},"level":"law","status":"active","topics":["investment","tax"],"docNumber":"Republic Act No. 5685","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5685_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4482-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution, Marcelina S. Aquino is hereby authorized to transfer, assign, sell or mortgage in favor of any banking or financing institution the franchises granted under Republic Acts Numbered Six hundred ninety-seven and Seven hundred fifty-seven, which were transferred to her by authority of Republic Acts Numbered Thirty-nine hundred seventy-one and Thirty-nine hundred seventy-two, as well as the certificates of public convenience granted or to be granted by the Public Service Commission to her pursuant to the above-mentioned Acts, including all assets and property operated thereunder, located in the City of Butuan and in the Province of Agusan and the municipalities and mu­nicipal districts thereof."}},{"id":"PH-H4482-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without Executive approval, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4483"] = {"id":"PH-H4483","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5686_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating Barrio Sampaguita in Lipa City","orig":"An Act Creating Barrio Sampaguita in Lipa City"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5686","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5686_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4483-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Sarapalocan in Barrio Cumba, Lipa City, is hereby separated from said barrio, and converted into a distinct and independent barrio of said city, to be known as Barrio Sampaguita."}},{"id":"PH-H4483-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4484"] = {"id":"PH-H4484","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5687_1969.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Constituting the Third Representative District of the Province of Batangas Into a Separate School Division","orig":"An Act Constituting the Third Representative District of the Province of Batangas Into a Separate School Division"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5687","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5687_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4484-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Third Representative District of the Province of Batangas shall constitute one separate school division with permanent station in the Municipality of Tanauan."}},{"id":"PH-H4484-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The superintendent of schools for the said division shall be appointed as now provided by law."}},{"id":"PH-H4484-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of fifty thousand pesos is authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, to carry out the purpose of this Act during the fiscal year nineteen hundred sixty-nine. Thereafter, such sums as may be needed for the same purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H4484-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4485"] = {"id":"PH-H4485","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5688_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for the Establishment of a Breeding Station in the Municipality of Tanauan, Province of Batangas, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of a Breeding Station in the Municipality of Tanauan, Province of Batangas, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5688","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5688_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4485-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Director of Animal Industry, a breeding station in the Municipality of Tanauan, Province of Batangas, to be known as Tanauan Breeding Station."}},{"id":"PH-H4485-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of five hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of the said station, including the purchase of its site, for the fiscal year nineteen hundred sixty-nine. Thereafter, such sums as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H4485-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4486"] = {"id":"PH-H4486","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5689_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating the Municipality of Laurel in the Province of Batangas","orig":"An Act Creating the Municipality of Laurel in the Province of Batangas"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5689","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5689_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4486-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Barrios Bayuyungan, Ticub, Balakilong, Bugaan, Borinayan, As-is, San Gabriel, and Buso-buso in the Municipality of Talisay, Province of Batangas, are separated from said municipality and constituted into a distinct and independent municipality to be known as the Municipality of Laurel, same province. The seat of government of the new municipality shall be in the present site of Barrio Bayuyungan."}},{"id":"PH-H4486-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first mayor, vice-mayor, and councilors of the new municipality shall be elected in the next general elections for local officials."}},{"id":"PH-H4486-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4487"] = {"id":"PH-H4487","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5690_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Increasing the Bed Capacity of Lipa City Hospital and Converting the Same Into a National Hospital","orig":"An Act Increasing the Bed Capacity of Lipa City Hospital and Converting the Same Into a National Hospital"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 5690","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5690_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4487-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Lipa City Hospital in Lipa City is hereby converted into a national hospital with an authorized bed capacity of fifty beds."}},{"id":"PH-H4487-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The additional sum of two hundred thousand pesos is hereby authorized to be appropriated in the next General Appropriations Act for its maintenance and operation.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4488"] = {"id":"PH-H4488","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5691_1969.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Cateel市","en":"An Act Establishing a Vocational High School in the Municipality of Cateel, Province of Davao Oriental, to Be Known as Cateel Vocational High School, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing a Vocational High School in the Municipality of Cateel, Province of Davao Oriental, to Be Known as Cateel Vocational High School, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5691","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5691_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 4 条，缺 3）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4488-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established under the supervision of the Director of Vocational Education a vocational high school to be known as Cateel Vocational High School in the Municipality of Cateel, Province of Davao Oriental."}},{"id":"PH-H4488-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said school during the school year commencing in nineteen hundred seventy. Thereafter, such sum as may be necessary for its maintenance and operation shall be included in the annual General Appropriations Act."}},{"id":"PH-H4488-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4489"] = {"id":"PH-H4489","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5692_1969.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting Alfredo Angeles a Franchise to Install, Maintain and Operate An Electric Light, Heat, Power System and An Ice Plant in the Municipality of Molave, Province of Zamboanga Del Sur","orig":"An Act Granting Alfredo Angeles a Franchise to Install, Maintain and Operate An Electric Light, Heat, Power System and An Ice Plant in the Municipality of Molave, Province of Zamboanga Del Sur"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5692","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5692_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4489-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred thirty-two, and to the provisions of the Constitution, there is granted to Alfredo Angeles in the Municipality of Molave, Province of Zamboanga del Sur, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to install, maintain and operate electric light, heat, power system and an ice plant for the purpose of generating, distributing electric light, heat and/or power and manufacturing ice for sale within the limits of the said municipality."}},{"id":"PH-H4489-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H4489-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee shall manufacture and supply ice up to the limit of the capacity of his plant, said limit to be determined by the Public Service Commission."}},{"id":"PH-H4489-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All the apparatus and appurtenances to be used by the grantee shall be modern, safe and first class in every respect, and the grantee shall, whenever the Public Service Commission shall determine that public interest reasonably requires it, change or alter any of the apparatus and appurtenances at grantee's expense."}},{"id":"PH-H4489-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"If the grantee shall not commence the manufacture and distribution of ice and the generation of electric light, heat and power in the Municipality of Molave, Province of Zamboanga del Sur, within one year from the approval of this Act, unless prevented by an act of God or force majeure, martial law, riot, civil commotion, usurpation by a military power or any other cause beyond the grantee's control, this franchise shall be null and void."}},{"id":"PH-H4489-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This franchise is granted subject to the provisions of the Constitution and Commonwealth Act Numbered One hundred forty-six, as amended, and with the understanding and upon the condition that it shall be subject to amendment, alteration, or renewal by the Congress of the Philippines when public interest so requires."}},{"id":"PH-H4489-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The books, records and accounts of the grantee shall always be open to the inspection of the Auditor General or his authorized representatives, and it shall be the duty of the grantee to submit to the Auditor General quarterly reports in duplicate showing the gross receipts for the quarter past."}},{"id":"PH-H4489-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall be liable to pay the same taxes, unless exempted therefrom, on his business, real estate, buildings, and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay."}},{"id":"PH-H4489-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"It is expressly provided that in the event the Government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender his franchise and will turn over to the government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H4489-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without Executive approval, June, 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4490"] = {"id":"PH-H4490","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5693_1969.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Cateel市","en":"An Act Establishing a National Agricultural High School in the Municipality of Cateel, Province of Davao Oriental, to Be Known as Cateel National Agricultural High School, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing a National Agricultural High School in the Municipality of Cateel, Province of Davao Oriental, to Be Known as Cateel National Agricultural High School, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education","environment"],"docNumber":"Republic Act No. 5693","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5693_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4490-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established a national agricultural high school in the Municipality of Cateel, Province of Davao Oriental, to be known as Cateel Agricultural High School."}},{"id":"PH-H4490-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Director of Vocational Education is hereby empowered to organize said school. He may locate or acquire, or cause to be located or acquired, any suitable site in the Municipality of Cateel, Province of Davao Oriental, after previous consultation with the Director of the Bureau of Forestry, the Director of the Bureau of Lands, and the Provincial Governor."}},{"id":"PH-H4490-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of said school during the school year commencing in nineteen hundred seventy. Thereafter, the necessary funds for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H4490-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4491"] = {"id":"PH-H4491","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5694_1969.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Converting Negros Occidental High School in the City of Bacolod Into a National High School to Be Known as Negros Occidental General Comprehensive High School, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Converting Negros Occidental High School in the City of Bacolod Into a National High School to Be Known as Negros Occidental General Comprehensive High School, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5694","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5694_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4491-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Negros Occidental High School in the City of Bacolod is hereby converted into a national, high school, to be known as Negros Occidental General Comprehensive High School. Comprehensive curriculum which includes both academic and industrial arts and handicraft courses shall be offered. The Secretary is hereby empowered to reorganize the said school accordingly."}},{"id":"PH-H4491-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Upon organization of Negros Occidental General Comprehensive High School, the assets, liabilities, personnel, equipment and records of Negros Occidental High School shall stand transferred to the Negros Occidental General Comprehensive High School."}},{"id":"PH-H4491-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of three hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of the said school in addition to its matriculation and tuition fees, and other revenues."}},{"id":"PH-H4491-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without Executive approval, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4492"] = {"id":"PH-H4492","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5695_1969.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for the Establishment of a National Shrine in the City of Lapu-Lapu, Province of Cebu, to Be Known as the Liberty Shrine, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of a National Shrine in the City of Lapu-Lapu, Province of Cebu, to Be Known as the Liberty Shrine, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5695","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5695_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4492-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is established in the City of Lapu-lapu, Province of Cebu, a national shrine, to be known as the Liberty Shrine, which shall comprise the site of the Magellan Monument, including said monument and other improvements built thereon, which site is the approximate place where the historic battle of Mactan took place on April 27, 1521, between the forces of Ferdinand Magellan of Spain, and Lapu-lapu, the native chieftain, as well as the lands adjacent thereto whose acquisition by negotiation or expropriation is hereby authorized."}},{"id":"PH-H4492-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"There shall be constructed on any vacant place on the land where the battle of Mactan took place, a monument to the native chieftain Lapu-lapu, and a Liberty House, wherein shall be depicted the important personages, places and events, including laws, customs and traditions in the history of this nation before and during the coming of Magellan."}},{"id":"PH-H4492-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"To carry out the purposes of this Act, including expenses for development and beautification, payment of adjacent lots which shall be acquired through negotiation or expropriation, the construction of a park and of a suitable resthouse for visitors and tourists thereon, and the payment of salaries of necessary personnel, the sum of one million pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated. Such sums as may be necessary for the improvement and maintenance of the said Liberty Shrine in subsequent years shall be included in the annual General Appropriations Act."}},{"id":"PH-H4492-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4493"] = {"id":"PH-H4493","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5696_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Amending Section One of Republic Act Numbered Forty-Three Hundred Ninety-One, Entitled \"An Act Converting the Dipolog Communal Irrigation System in the Municipality of Dipolog, Province of Zamboanga Del Norte, Into a National Irrigation System.\"","orig":"An Act Amending Section One of Republic Act Numbered Forty-Three Hundred Ninety-One, Entitled \"An Act Converting the Dipolog Communal Irrigation System in the Municipality of Dipolog, Province of Zamboanga Del Norte, Into a National Irrigation System.\""},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5696","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5696_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4493-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Forty-three hundred and ninety-one is hereby amended to read as follows:\n\"Section 1. The Dipolog Communal Irrigation System in the Municipality of Dipolog, Province of Zamboanga del Norte, is hereby converted into a national irrigation system, subject to the supervision of the Director of Public Works: Provided, however, That the administration of the system may be delegated to the municipal government of Dipolog, Province of Zamboanga del Norte, by the Secretary of Public Works and Communications, upon the recommendation of the Director of Public Works.\""}},{"id":"PH-H4493-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4494"] = {"id":"PH-H4494","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5697_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing An Additional Judge for the City Court of the City of Butuan, Amending for the Purpose Section Seventy-Six of the Charter of the City of Butuan","orig":"An Act Providing An Additional Judge for the City Court of the City of Butuan, Amending for the Purpose Section Seventy-Six of the Charter of the City of Butuan"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 5697","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5697_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4494-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section seventy-six of Republic Act Numbered Five hundred twenty-three, otherwise known as the Charter of the City of Butuan, is amended to read as follows:\n\"Section 76. Regular, auxiliary and acting judges of the city court. -There shall be a city court for the City of Butuan which shall have two branches for which the two judges thereof shall be known, respectively, as judge of the first and second branch, and an auxiliary city judge.\n\"The city judges may, upon proper application, be allowed a vacation of not more than thirty days every year with salary. The auxiliary city judge shall discharge the duties of the city judge in case of absence, incapacity or inability of the latter until he assumes his post, or until a new judge shall have been appointed. During his incumbency the auxiliary city judge shall enjoy the powers, emoluments and privileges of the city judge who shall not receive any remuneration therefor except the salary to which he is entitled by reason of his vacation provided for in this Act.\n\"In case of absence, incapacity or inability of both the city judges and the auxiliary city judge, the Secretary of Justice shall designate the justice of the peace of any of the adjoining municipalities to preside over the city court, and he shall hold the office temporarily until the regular incumbent or the auxiliary judge thereof shall have resumed office or until another judge shall have been appointed in accordance with the provisions of this Act. The justice of the peace so designated shall receive his salary as justice of the peace plus seventy per cent of the salary of the city judge whose office he has temporarily assumed. The city judges shall receive a salary of not exceeding fifteen thousand pesos per annum, one-half of which shall be paid by the city government and the other half by the National Government.\""}},{"id":"PH-H4494-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
  FT["PH-H4495"] = {"id":"PH-H4495","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5698_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Butuan市","en":"An Act Creating the Positions of Assistant City Fiscal in the City of Butuan, Amending for the Purpose Section Twenty-Four of Republic Act Numbered Five Hundred Twenty-Three, Otherwise Known as the Charter of the City of Butuan","orig":"An Act Creating the Positions of Assistant City Fiscal in the City of Butuan, Amending for the Purpose Section Twenty-Four of Republic Act Numbered Five Hundred Twenty-Three, Otherwise Known as the Charter of the City of Butuan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5698","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5698_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4495-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The first paragraph of Section twenty-four of Republic Act Numbered Five hundred twenty-three, otherwise known as the Charter of the City of Butuan, is hereby amended to read as follows:\n\"Section 24. The city fiscal and his assistants- His powers, duties and compensation. - The law department shall consist of the city fiscal who shall be the chief legal adviser of the city, and four assistants who shall be known respectively as the first, second, third, and fourth assistant city fiscals. Said assistant city fiscals shall be appointed by the President of the Philippines, with the consent of the Commission on Appointments. The compensation of the city fiscal, the first, second, third, and fourth assistant city fiscals shall be that provided by law for officials of the same rank and performing the same functions. The city fiscal shall have the following powers and duties:\""}},{"id":"PH-H4495-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p63"};
